create schema if not exists game_private;
revoke all on schema game_private from public,anon;
grant usage on schema game_private to authenticated;
create table public.game_wallets(user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,coins integer not null default 0 check(coins>=0),xp integer not null default 0,character text not null default 'usagi' check(character in ('usagi','hachiware','kurimanju','shisa','momonga','furuhonya','anoko')),background text not null default 'cloud' check(background in ('cloud','night','forest','picnic')),created_at timestamptz not null default now());
create table public.game_items(id text primary key,name text not null,price integer not null check(price>0),kind text not null,description text not null);
insert into public.game_items values
('mug','따뜻한 머그잔',400,'mug','오늘의 공부에 곁들이는 따뜻한 한 잔'),('snack','간식 접시',600,'snack','달콤한 도넛과 작은 쿠키'),('books','차곡차곡 책',800,'books','하나씩 쌓여가는 나의 공부'),('cushion','구름 쿠션',1500,'cushion','폭신하게 기대어 쉬어가요'),('plant','초록 화분',1600,'plant','방 안에 작은 초록빛'),('lamp','독서 스탠드',1800,'lamp','조용한 밤을 밝혀주는 빛'),('chair','나무 의자',2800,'chair','내가 가장 좋아하는 자리'),('rug','동그란 러그',3200,'rug','맨발로 밟고 싶은 폭신한 바닥'),('shelf','작은 책장',3800,'shelf','좋아하는 물건을 차곡차곡'),('desk','나의 공부 책상',6000,'desk','마음에 쏙 드는 공부 자리'),('bed','포근한 침대',7500,'bed','공부를 마치고 푹 쉬어요'),('sofa','느긋한 소파',8000,'sofa','친구와 나란히 앉는 자리'),('forest','숲속 배경',12000,'theme','싱그러운 숲이 보이는 방'),('night','별이 뜨는 밤',15000,'theme','반짝이는 별과 함께하는 밤');
create table public.game_inventory(user_id uuid not null references auth.users(id) on delete cascade,item_id text not null references public.game_items(id),placed boolean not null default false,x numeric not null default 50 check(x between 5 and 95),y numeric not null default 65 check(y between 35 and 90),created_at timestamptz not null default now(),primary key(user_id,item_id));
create table public.game_rewards(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null,source_key text not null,attempt_id uuid references public.attempts(id) on delete set null,base integer not null,random_bonus integer not null,correct_bonus integer not null default 0,total integer not null,minutes integer not null default 0,notified_at timestamptz,created_at timestamptz not null default now(),unique(user_id,kind,source_key));
create index game_rewards_attempt on public.game_rewards(attempt_id);create index game_rewards_user_date on public.game_rewards(user_id,created_at desc);
create table public.pomodoro_catalog(video_id text primary key,title text not null,duration integer not null,sessions jsonb not null);
alter table public.watch_rooms add column mode text not null default 'watch' check(mode in ('watch','pomodoro'));
create table public.pomodoro_progress(user_id uuid not null references auth.users(id) on delete cascade,room_id uuid not null references public.watch_rooms(id) on delete cascade,cycle integer not null,focus_seconds double precision not null default 0,goal text not null default '' check(length(goal)<=500),completed_at timestamptz,reward_id uuid references public.game_rewards(id),created_at timestamptz not null default now(),primary key(user_id,room_id,cycle));
create index pomodoro_progress_room on public.pomodoro_progress(room_id);create index pomodoro_progress_reward on public.pomodoro_progress(reward_id);
create table game_private.presence(user_id uuid primary key references auth.users(id) on delete cascade,room_id uuid,last_at timestamptz not null,last_position double precision not null,last_playing boolean not null);
alter table game_private.presence enable row level security;revoke all on game_private.presence from public,anon,authenticated;
