alter table public.game_wallets enable row level security;alter table public.game_items enable row level security;alter table public.game_inventory enable row level security;alter table public.game_rewards enable row level security;alter table public.pomodoro_catalog enable row level security;alter table public.pomodoro_progress enable row level security;
create policy wallet_owner on public.game_wallets for select to authenticated using(user_id=(select auth.uid()));
create policy inventory_owner on public.game_inventory for select to authenticated using(user_id=(select auth.uid()));
create policy rewards_owner on public.game_rewards for select to authenticated using(user_id=(select auth.uid()));
create policy progress_owner on public.pomodoro_progress for select to authenticated using(user_id=(select auth.uid()));
create policy items_read on public.game_items for select to authenticated using(true);create policy pomodoro_read on public.pomodoro_catalog for select to authenticated using(true);
revoke all on public.game_wallets,public.game_items,public.game_inventory,public.game_rewards,public.pomodoro_catalog,public.pomodoro_progress from anon,authenticated;
grant select on public.game_wallets,public.game_items,public.game_inventory,public.game_rewards,public.pomodoro_catalog,public.pomodoro_progress to authenticated;
create function game_private.ensure_wallet() returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception '로그인이 필요합니다.';end if;insert into public.game_wallets(user_id) values(auth.uid()) on conflict do nothing;end;$$;
create function game_private.state() returns jsonb language plpgsql security definer set search_path='' as $$begin
 perform game_private.ensure_wallet();return jsonb_build_object('wallet',(select to_jsonb(w) from public.game_wallets w where user_id=auth.uid()),'inventory',coalesce((select jsonb_agg(to_jsonb(i)) from public.game_inventory i where user_id=auth.uid()),'[]'::jsonb),'items',(select jsonb_agg(to_jsonb(i) order by price) from public.game_items i),'recent',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from public.game_rewards where user_id=auth.uid() order by created_at desc limit 12) r),'[]'::jsonb),'communityMinutes',(select coalesce(sum(minutes),0) from public.game_rewards));end;$$;
create function game_private.attempt_reward() returns trigger language plpgsql security definer set search_path='' as $$declare b integer:=floor(random()*5)::integer;extra integer:=case when new.is_correct then 2 else 0 end;rid uuid;begin
 insert into public.game_rewards(user_id,kind,source_key,attempt_id,base,random_bonus,correct_bonus,total) values(new.user_id,'quiz',new.question_id::text||':'||(new.answered_at at time zone 'Asia/Seoul')::date,new.id,3,b,extra,3+b+extra) on conflict do nothing returning id into rid;
 if rid is not null then insert into public.game_wallets(user_id,coins,xp) values(new.user_id,3+b+extra,1) on conflict(user_id) do update set coins=public.game_wallets.coins+3+b+extra,xp=public.game_wallets.xp+1;end if;return new;end;$$;
create trigger game_attempt_reward after insert on public.attempts for each row execute function game_private.attempt_reward();
create function game_private.take_attempt(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.game_rewards;begin
 if auth.uid() is null then raise exception '로그인이 필요합니다.';end if;update public.game_rewards set notified_at=now() where attempt_id=p_id and user_id=auth.uid() and notified_at is null returning * into r;if not found then return null;end if;return to_jsonb(r);end;$$;
create function game_private.buy(p_item text) returns jsonb language plpgsql security definer set search_path='' as $$declare cost integer;balance integer;begin
 perform game_private.ensure_wallet();select coins into balance from public.game_wallets where user_id=auth.uid() for update;
 select price into cost from public.game_items where id=p_item;if not found then raise exception '상품을 찾을 수 없습니다.';end if;
 if exists(select 1 from public.game_inventory where user_id=auth.uid() and item_id=p_item) then return game_private.state();end if;
 if balance<cost then raise exception '코인을 조금 더 모아주세요.';end if;update public.game_wallets set coins=coins-cost where user_id=auth.uid();insert into public.game_inventory(user_id,item_id) values(auth.uid(),p_item);return game_private.state();end;$$;
create function game_private.place(p_item text,p_placed boolean,p_x numeric,p_y numeric) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null then raise exception '로그인이 필요합니다.';end if;if p_x is null or p_y is null or p_placed is null or not(p_x between 5 and 95 and p_y between 35 and 90) then raise exception '배치 위치를 확인해주세요.';end if;
 update public.game_inventory set placed=p_placed,x=p_x,y=p_y where user_id=auth.uid() and item_id=p_item and exists(select 1 from public.game_items where id=p_item and kind<>'theme');if not found then raise exception '보유한 가구를 선택해주세요.';end if;end;$$;
create function game_private.style(p_character text,p_background text) returns void language plpgsql security definer set search_path='' as $$begin
 perform game_private.ensure_wallet();if p_character not in ('usagi','hachiware','kurimanju','shisa','momonga','furuhonya','anoko') or p_character is null then raise exception '캐릭터를 선택해주세요.';end if;
 if p_background is null or p_background not in ('cloud','night','forest','picnic') then raise exception '배경을 선택해주세요.';end if;
 if p_background in ('night','forest') and not exists(select 1 from public.game_inventory where user_id=auth.uid() and item_id=p_background) then raise exception '구매한 배경을 선택해주세요.';end if;
 if p_background='picnic' and (select coalesce(sum(minutes),0) from public.game_rewards)<3000 then raise exception '함께 공부 목표를 먼저 달성해주세요.';end if;
 update public.game_wallets set character=p_character,background=p_background where user_id=auth.uid();end;$$;
create function game_private.visit(p_user uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null then raise exception '로그인이 필요합니다.';end if;return (select jsonb_build_object('name',coalesce(u.raw_user_meta_data->>'user_name','친구'),'character',w.character,'background',w.background,'inventory',coalesce((select jsonb_agg(to_jsonb(i)-'user_id') from public.game_inventory i where i.user_id=p_user and placed),'[]'::jsonb)) from public.game_wallets w join auth.users u on u.id=w.user_id where w.user_id=p_user);end;$$;
create function game_private.pomo_create(p_video text) returns jsonb language plpgsql security definer set search_path='' as $$declare data jsonb;rid uuid;begin
 if not exists(select 1 from public.pomodoro_catalog where video_id=p_video) then raise exception '등록된 뽀모도로 영상을 선택해주세요.';end if;data:=watch_private.create_room(p_video);rid:=(data->'room'->>'id')::uuid;update public.watch_rooms set mode='pomodoro' where id=rid;return watch_private.snapshot(rid);end;$$;
create function game_private.goal(p_room uuid,p_cycle integer,p_goal text) returns void language plpgsql security definer set search_path='' as $$declare r public.watch_rooms;total integer;begin
 if not watch_private.can_access(p_room) then raise exception '방에 먼저 참여해주세요.';end if;select * into r from public.watch_rooms where id=p_room and mode='pomodoro';if not found then raise exception '뽀모도로 방이 아닙니다.';end if;select jsonb_array_length(sessions) into total from public.pomodoro_catalog where video_id=r.video_id;
 if p_cycle is null or p_cycle<0 or p_cycle>=total or p_goal is null or length(p_goal)>500 then raise exception '목표를 확인해주세요.';end if;
 insert into public.pomodoro_progress(user_id,room_id,cycle,goal) values(auth.uid(),p_room,p_cycle,p_goal) on conflict(user_id,room_id,cycle) do update set goal=excluded.goal;end;$$;
create function game_private.heartbeat(p_room uuid,p_position double precision,p_active boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.watch_rooms;prior game_private.presence;s jsonb;idx integer:=0;elapsed double precision;advance double precision;credit double precision;expected double precision;valid boolean;begin
 if not watch_private.can_access(p_room) then raise exception '방에 먼저 참여해주세요.';end if;select * into r from public.watch_rooms where id=p_room and mode='pomodoro';if not found then raise exception '뽀모도로 방이 아닙니다.';end if;
 if p_position is null or p_active is null or not(p_position between 0 and 604800) then raise exception '재생 위치를 확인해주세요.';end if;
 perform game_private.ensure_wallet();perform 1 from public.game_wallets where user_id=auth.uid() for update;
 select * into prior from game_private.presence where user_id=auth.uid();expected:=r.position+case when r.playing and not r.closed then greatest(0,extract(epoch from(clock_timestamp()-r.updated_at)))*r.playback_rate else 0 end;
 valid:=abs(p_position-expected)<=8 and r.playback_rate=1 and not r.closed;
 elapsed:=case when prior.last_at is not null then greatest(0,extract(epoch from(clock_timestamp()-prior.last_at))) else 0 end;advance:=p_position-coalesce(prior.last_position,p_position);
 for s in select value from public.pomodoro_catalog c,jsonb_array_elements(c.sessions) where c.video_id=r.video_id loop
  credit:=0;if valid and (p_active or not r.playing) and prior.last_playing and prior.room_id=p_room and elapsed<=90 and advance between 0 and elapsed+5 then credit:=least(elapsed+1,advance)*greatest(0,least(p_position,(s->>'end')::double precision)-greatest(prior.last_position,(s->>'start')::double precision))/greatest(advance,0.001);end if;
  if credit>0 then insert into public.pomodoro_progress(user_id,room_id,cycle,focus_seconds) values(auth.uid(),p_room,idx,credit) on conflict(user_id,room_id,cycle) do update set focus_seconds=least((s->>'end')::double precision-(s->>'start')::double precision,public.pomodoro_progress.focus_seconds+credit);end if;
  if valid and p_position>=(s->>'end')::double precision then update public.pomodoro_progress set completed_at=coalesce(completed_at,now()) where user_id=auth.uid() and room_id=p_room and cycle=idx and focus_seconds>=60;end if;idx:=idx+1;
 end loop;
 insert into game_private.presence values(auth.uid(),p_room,clock_timestamp(),p_position,p_active and r.playing and valid) on conflict(user_id) do update set room_id=excluded.room_id,last_at=excluded.last_at,last_position=excluded.last_position,last_playing=excluded.last_playing;
 return coalesce((select jsonb_agg(to_jsonb(p) order by cycle) from public.pomodoro_progress p where user_id=auth.uid() and room_id=p_room),'[]'::jsonb);end;$$;
create function game_private.pomo_claim(p_room uuid,p_cycle integer,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare p public.pomodoro_progress;r public.game_rewards;b integer;extra integer;roll double precision:=random();mins integer;begin
 if auth.uid() is null or p_confirm is distinct from true then raise exception '공부 완료를 확인해주세요.';end if;
 perform game_private.ensure_wallet();perform 1 from public.game_wallets where user_id=auth.uid() for update;
 select * into p from public.pomodoro_progress where user_id=auth.uid() and room_id=p_room and cycle=p_cycle for update;if not found or p.completed_at is null or p.focus_seconds<60 then raise exception '공부 구간을 마친 뒤 받을 수 있습니다.';end if;
 if p.reward_id is not null then return null;end if;mins:=floor((p.focus_seconds+5)/60)::integer;b:=mins*2;
 extra:=floor(b*case when roll<0.6 then (10+floor(random()*11))/100.0 when roll<0.9 then (30+floor(random()*21))/100.0 when roll<0.99 then (80+floor(random()*21))/100.0 else 2 end)::integer;
 insert into public.game_rewards(user_id,kind,source_key,base,random_bonus,total,minutes,notified_at) values(auth.uid(),'pomodoro',p_room::text||':'||p_cycle,b,extra,b+extra,mins,now()) returning * into r;
 update public.pomodoro_progress set reward_id=r.id where user_id=auth.uid() and room_id=p_room and cycle=p_cycle;perform game_private.ensure_wallet();update public.game_wallets set coins=coins+r.total,xp=xp+mins where user_id=auth.uid();return to_jsonb(r);end;$$;
revoke all on all functions in schema game_private from public,anon,authenticated;
grant execute on function game_private.state(),game_private.take_attempt(uuid),game_private.buy(text),game_private.place(text,boolean,numeric,numeric),game_private.style(text,text),game_private.visit(uuid),game_private.pomo_create(text),game_private.goal(uuid,integer,text),game_private.heartbeat(uuid,double precision,boolean),game_private.pomo_claim(uuid,integer,boolean) to authenticated;
