create function public.game_attempt_reward(p_id uuid) returns jsonb language sql security invoker set search_path='' as $$select game_private.take_attempt(p_id);$$;
create function public.game_buy(p_item text) returns jsonb language sql security invoker set search_path='' as $$select game_private.buy(p_item);$$;
create function public.game_place(p_item text,p_placed boolean,p_x numeric,p_y numeric) returns void language sql security invoker set search_path='' as $$select game_private.place(p_item,p_placed,p_x,p_y);$$;
create function public.game_style(p_character text,p_background text) returns void language sql security invoker set search_path='' as $$select game_private.style(p_character,p_background);$$;
create function public.game_visit(p_user uuid) returns jsonb language sql security invoker set search_path='' as $$select game_private.visit(p_user);$$;
create function public.pomo_create(p_video text) returns jsonb language sql security invoker set search_path='' as $$select game_private.pomo_create(p_video);$$;
create function public.pomo_goal(p_room uuid,p_cycle integer,p_goal text) returns void language sql security invoker set search_path='' as $$select game_private.goal(p_room,p_cycle,p_goal);$$;
create function public.pomo_heartbeat(p_room uuid,p_position double precision,p_active boolean) returns jsonb language sql security invoker set search_path='' as $$select game_private.heartbeat(p_room,p_position,p_active);$$;
create function public.pomo_claim(p_room uuid,p_cycle integer,p_confirm boolean) returns jsonb language sql security invoker set search_path='' as $$select game_private.pomo_claim(p_room,p_cycle,p_confirm);$$;
revoke all on function public.game_state(),public.game_attempt_reward(uuid),public.game_buy(text),public.game_place(text,boolean,numeric,numeric),public.game_style(text,text),public.game_visit(uuid),public.pomo_create(text),public.pomo_goal(uuid,integer,text),public.pomo_heartbeat(uuid,double precision,boolean),public.pomo_claim(uuid,integer,boolean) from public,anon;
grant execute on function public.game_state(),public.game_attempt_reward(uuid),public.game_buy(text),public.game_place(text,boolean,numeric,numeric),public.game_style(text,text),public.game_visit(uuid),public.pomo_create(text),public.pomo_goal(uuid,integer,text),public.pomo_heartbeat(uuid,double precision,boolean),public.pomo_claim(uuid,integer,boolean) to authenticated;
-- Pomodoro catalog is immutable for a room; keep ordinary watch rooms flexible.
create function game_private.guard_pomo_room() returns trigger language plpgsql set search_path='' as $$begin if old.mode='pomodoro' and (new.video_id<>old.video_id or new.playback_rate<>1) then raise exception '뽀모도로 방의 영상과 배속은 고정되어 있습니다.';end if;return new;end;$$;
create trigger guard_pomo_room before update on public.watch_rooms for each row execute function game_private.guard_pomo_room();
